tasks.check:
set -o pipefail
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
D=data/stories/continuity-initiative
CH=$(git status --porcelain | grep -v '^?? .venv' | awk '{print $2}' | sort | tr '\n' ' ')
for f in $CH; do case "$f" in $D/storylets.md|$D/storylet-routes.yaml|$D/handoffs.yaml|$D/knowledge.yaml) ;; *) echo "WHY: edited file outside ownership: $f"; exit 1;; esac; done
[ -n "$CH" ] || { echo "WHY: nothing changed"; exit 1; }
git diff --quiet -- $D/plot.md || { echo "WHY: plot.md was edited"; exit 1; }
grep -n "reunion is brief\|reunites with Kristin briefly\|Their reunion is brief\|reunion is interrupted\|without requiring an extended reunion" $D/storylets.md $D/storylet-routes.yaml $D/handoffs.yaml $D/knowledge.yaml && { echo "WHY: old reunion wording remains"; exit 1; }
grep -n "Michelle triggers" $D/storylets.md $D/storylet-routes.yaml $D/knowledge.yaml && { echo "WHY: 'Michelle triggers' still in storylets/routes/knowledge"; exit 1; }
for f in $D/storylets.md $D/storylet-routes.yaml $D/knowledge.yaml; do grep -qi "unhurried\|signal" $f || { echo "WHY: no unhurried/signal wording in $f"; exit 1; }; done
grep -q "unhurried" $D/knowledge.yaml || { echo "WHY: knowledge.yaml lacks the unhurried reunion"; exit 1; }
grep -q "Kristin gives the signal" $D/handoffs.yaml || { echo "WHY: handoffs lacks 'Kristin gives the signal'"; exit 1; }
$PY -c "import yaml,sys
for f in ['storylet-routes','handoffs','knowledge']: yaml.safe_load(open('$D/'+f+'.yaml'))" || { echo "WHY: yaml invalid"; exit 1; }
$PY -m pytest -q -p no:cacheprovider tests/test_markdown_story_package.py tests/test_package_audit.py tests/test_scene_roleplay_contract.py tests/test_3a_records_followup.py tests/test_disclosure_guards.py tests/test_scene_relative_pacing.py tests/test_spine_expected_reveals.py tests/test_late_scene_repro.py tests/test_knowledge_leakage_matrix.py tests/test_narration_place_names.py tests/test_speaker_presence.py tests/test_surface_gates_scope.py tests/test_medical_records_alias.py tests/test_3ab_spine_prompts.py tests/test_2c_paths_repro.py 2>&1 | tail -25 || { echo "WHY: suites failed"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/3a-reunion-radio
mkdir -p $OUT && git add -A -- data/stories/continuity-initiative && git diff --cached > $OUT/3a.patch && wc -l $OUT/3a.patch && git diff --cached --stat | tail -8
